<script setup lang="ts">
import ConsoleDiscardChangesDialog from '~/components/console/ConsoleDiscardChangesDialog.vue'
const discard=useDiscardChanges(()=>!!busy.value||sending.value||notificationSaving.value)
import AdminConsole from '../../components/console/AdminConsole.vue'
import ConsoleDrawer from '../../components/console/ConsoleDrawer.vue'
import ConsoleQueryButton from '../../components/console/ConsoleQueryButton.vue'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleDataTable from '@orangezh1/qisvc-console-ui/components/ConsoleDataTable'
import {dateTime} from '../../utils/update-center'
const props=defineProps<{view:'channels'|'notifications'|'logs'}>()
const pageTitle=props.view==='channels'?'短信配置':props.view==='notifications'?'通知设置':'发送记录'
type Config={enabled:boolean;signature:string;appId:string;region:string;loginTemplate:string;registerTemplate:string;resetTemplate:string;intervalSeconds:number;phoneDailyLimit:number;ipHourlyLimit:number}
type Channel={provider:string;label:string;config:Config;hasCredentials:boolean;maskedAccessKeyId:string;isDefault:boolean}
type Notification={purpose:string;label:string;typeLabel:string;business:string;provider:string|null;providerLabel:string;templateId:string;content:string;enabled:boolean;templates:{aliyun:string;tencent:string}}
type View={notifications:Notification[];applicationKey:string|null;applications:{key:string;name:string}[];version:number;defaultProvider:string|null;channels:Channel[];canWrite:boolean;testEnabled:boolean;updatedAt:string|null}
type Delivery={id:string;requestId:string;provider:string;purposeLabel:string;phoneMasked:string;status:string;errorCode:string|null;receipt:string|null;createdAt:string;message:string}
type Logs={items:Delivery[];total:number;page:number;pageSize:number}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/sms-settings',toast=useToast()
const initial=await useAsyncData<View>('tenant-sms:'+props.view+':'+auth.session.value?.id+':'+tenantId,(_nuxt,{signal})=>auth.api<View>(endpoint,'GET',undefined,{signal}))
const data=ref<View|null>(initial.data.value??null),applicationKey=ref(data.value?.applicationKey||''),provider=ref('aliyun'),form=ref<Config|null>(null),baseline=ref(''),accessKeyId=ref(''),secret=ref(''),clearSecrets=ref(false),makeDefault=ref(false),busy=ref<'save'|'refresh'|'retry'|'application'|'check'|null>(null),error=ref(initial.error.value?.message||''),checkResult=ref<{message:string;checkedAt:string}|null>(null),checkError=ref('')
const channel=computed(()=>data.value?.channels.find(c=>c.provider===provider.value)),dirty=computed(()=>!!form.value&&(JSON.stringify(form.value)!==baseline.value||!!accessKeyId.value||!!secret.value||clearSecrets.value||makeDefault.value!==!!channel.value?.isDefault)),locked=computed(()=>!!busy.value||sending.value||!data.value?.canWrite)
const editOpen=ref(false),notificationOpen=ref(false),notificationForm=ref<Notification|null>(null),notificationBaseline=ref(''),notificationSaving=ref(false),notificationError=ref('')
const notificationDirty=computed(()=>!!notificationForm.value&&JSON.stringify(notificationForm.value)!==notificationBaseline.value)
const channelColumns=[{accessorKey:'label',header:'短信渠道'},{accessorKey:'config',header:'状态'},{id:'actions',header:'操作'}],notificationColumns=[{accessorKey:'label',header:'通知场景'},{accessorKey:'enabled',header:'状态'},{id:'actions',header:'操作'}]
function openSettings(value:string){if(busy.value||sending.value||dirty.value)return;provider.value=value;resetForm();editOpen.value=true}
function closeSettings(){if(busy.value||sending.value||notificationSaving.value)return;if(dirty.value){discard.request(()=>{resetForm();editOpen.value=false});return}editOpen.value=false}
function openNotification(row:Notification){notificationForm.value=structuredClone(toRaw(row));notificationBaseline.value=JSON.stringify(notificationForm.value);notificationError.value='';notificationOpen.value=true}
function closeNotification(){if(notificationSaving.value)return;if(notificationDirty.value){discard.request(cancelNotification);return}notificationOpen.value=false}
function cancelNotification(){if(!notificationSaving.value){notificationForm.value=null;notificationOpen.value=false;notificationError.value=''}}
async function saveNotification(){if(notificationSaving.value||!notificationForm.value||!notificationDirty.value||!data.value?.canWrite)return;notificationError.value='';if(!notificationForm.value.provider){notificationError.value='请先在短信配置中设置默认渠道';return}const content=notificationForm.value.content.trim();if(!content||content.length>500||(content.match(/\{code\}/g)||[]).length!==1||/[{}]/.test(content.replace('{code}',''))){notificationError.value='短信内容须包含一个 {code} 验证码变量，且不超过500字';return}notificationSaving.value=true;const {purpose,enabled,provider,templateId}=notificationForm.value;try{const value=await auth.api<View>(endpoint+'/'+encodeURIComponent(applicationKey.value)+'/notifications/'+purpose,'PUT',{version:data.value.version,enabled,provider,templateId,content},{signal:lifetime.signal});if(!disposed){fill(value);notificationBaseline.value=JSON.stringify(notificationForm.value);notificationOpen.value=false;toast.add({title:'通知设置已保存',color:'success'})}}catch(e:any){if(!disposed)notificationError.value=e.message||'保存失败，修改已保留'}finally{if(!disposed)notificationSaving.value=false}}

const lifetime=new AbortController();let disposed=false,logSequence=0,logController:AbortController|undefined
const emptyLogs=():Logs=>({items:[],total:0,page:1,pageSize:20}),logs=ref<Logs>(emptyLogs()),logAction=ref<'header'|'refresh'|'retry'|'page'|'background'|null>(null),logsError=ref('')
const testOpen=ref(false),sending=ref(false),testPhone=ref(''),testPurpose=ref('login'),testError=ref(''),testResult=ref<Delivery|null>(null),attempt=ref<{fingerprint:string;requestId:string}|null>(null)
const logChannel=props.view==='logs'?useRouteTab<string>('sms',['sms','wechat'],'channel'):ref('sms')
function changeLogChannel(value:string){logChannel.value=value}
watch(logChannel,()=>{logs.value=emptyLogs();void loadLogs('background',1)},{flush:'sync'})
const columns=[{accessorKey:'phoneMasked',header:'接收对象'},{accessorKey:'provider',header:'服务商'},{accessorKey:'purposeLabel',header:'用途'},{accessorKey:'status',header:'状态'},{accessorKey:'receipt',header:'受理编号 / 错误码'},{accessorKey:'createdAt',header:'创建时间'}]
const statusLabels:Record<string,string>={PENDING:'待发送',PREPARING:'准备中',CANCELLED:'已取消',SENDING:'提交中',ACCEPTED:'已受理',FAILED:'发送失败',UNKNOWN:'结果未知'}
function resetForm(){form.value=channel.value?structuredClone(toRaw(channel.value.config)):null;baseline.value=JSON.stringify(form.value);accessKeyId.value='';secret.value='';clearSecrets.value=false;makeDefault.value=!!channel.value?.isDefault;checkResult.value=null;checkError.value='';error.value='';discard.keep()}
function fill(value:View){data.value=value;applicationKey.value=value.applicationKey||'';resetForm()}
resetForm();if(initial.error.value)error.value=initial.error.value.message||'短信配置读取失败'
function selectProvider(value:string){if(busy.value||sending.value)return;if(dirty.value){discard.request(()=>{resetForm();selectProvider(value)});return}provider.value=value;resetForm()}
async function refresh(source:'refresh'|'retry'|'application'='refresh',key=applicationKey.value){
 if(busy.value||sending.value||notificationSaving.value)return;if(dirty.value||notificationDirty.value){discard.request(()=>{resetForm();cancelNotification();editOpen.value=false;void refresh(source,key)});return}busy.value=source;error.value=''
 try{const value=await auth.api<View>(endpoint+(key?'?applicationKey='+encodeURIComponent(key):''),'GET',undefined,{signal:lifetime.signal});if(!disposed){const changed=value.applicationKey!==applicationKey.value;fill(value);if(changed){logs.value=emptyLogs();attempt.value=null;testResult.value=null}if(props.view==='logs')void loadLogs('background',changed?1:logs.value.page)}}catch(e:any){if(!disposed)error.value=e.message||'短信配置读取失败'}finally{if(!disposed)busy.value=null}
}
async function save(){
 if(locked.value||!dirty.value||!data.value||!form.value||!applicationKey.value)return;busy.value='save';error.value=''
 try{const value=await auth.api<View>(endpoint+'/'+encodeURIComponent(applicationKey.value)+'/'+provider.value,'PUT',{version:data.value.version,config:JSON.parse(JSON.stringify(form.value)),accessKeyId:accessKeyId.value,secret:secret.value,clearSecrets:clearSecrets.value,makeDefault:makeDefault.value&&form.value.enabled},{signal:lifetime.signal});if(!disposed){fill(value);editOpen.value=false;toast.add({title:'短信配置已保存',color:'success'})}}catch(e:any){if(!disposed)error.value=e.message||'保存失败，修改已保留'}finally{if(!disposed)busy.value=null}
}
async function check(){
 if(locked.value||dirty.value||!data.value?.version)return;busy.value='check';checkResult.value=null;checkError.value=''
 try{const result=await auth.api<{message:string;checkedAt:string}>(endpoint+'/'+encodeURIComponent(applicationKey.value)+'/'+provider.value+'/check','POST',{version:data.value.version},{signal:lifetime.signal});if(!disposed)checkResult.value=result}catch(e:any){if(!disposed)checkError.value=e.message||'自检未通过'}finally{if(!disposed)busy.value=null}
}
async function loadLogs(source:'header'|'refresh'|'retry'|'page'|'background'='refresh',page=logs.value.page,pageSize=logs.value.pageSize){
 if(!applicationKey.value||disposed)return;logController?.abort();logController=new AbortController();const seq=++logSequence;logAction.value=source;logsError.value=''
 try{const value=await auth.api<Logs>((logChannel.value==='wechat'?endpoint.replace('sms-settings','subscription-settings'):endpoint)+'/'+encodeURIComponent(applicationKey.value)+'/logs?page='+page+'&pageSize='+pageSize,'GET',undefined,{signal:AbortSignal.any([lifetime.signal,logController.signal])});if(!disposed&&seq===logSequence)logs.value=value}catch(e:any){if(!disposed&&seq===logSequence)logsError.value=e.message||'发送记录读取失败'}finally{if(!disposed&&seq===logSequence)logAction.value=null}
}
function openTest(){testError.value='';if(!/^1[3-9]\d{9}$/.test(testPhone.value)){testError.value='请输入有效的大陆手机号';return}testOpen.value=true}
async function sendTest(){
 if(locked.value||dirty.value||!data.value?.testEnabled||!form.value?.enabled)return;if(!/^1[3-9]\d{9}$/.test(testPhone.value)){testError.value='请输入有效的大陆手机号';return}
 const fingerprint=JSON.stringify([applicationKey.value,provider.value,data.value.version,testPhone.value,testPurpose.value]);if(attempt.value?.fingerprint!==fingerprint)attempt.value={fingerprint,requestId:crypto.randomUUID()};sending.value=true;testError.value='';testResult.value=null
 try{const value=await auth.api<Delivery>(endpoint+'/'+encodeURIComponent(applicationKey.value)+'/'+provider.value+'/test','POST',{version:data.value.version,requestId:attempt.value.requestId,phone:testPhone.value,purpose:testPurpose.value},{signal:lifetime.signal});if(!disposed)testResult.value=value}catch(e:any){if(!disposed)testError.value=e.message||'结果未确认，请先查询发送记录'}finally{if(!disposed){sending.value=false;if(props.view==='logs')void loadLogs('background',1)}}
}
function closeTest(){if(!sending.value)testOpen.value=false}
onMounted(()=>{if(props.view==='logs')void loadLogs('background')})
onBeforeRouteLeave(to=>{if(!auth.session.value)return;if(busy.value||sending.value||notificationSaving.value){toast.add({title:'正在处理，请稍候再离开',color:'neutral'});return false}if(dirty.value||notificationDirty.value){discard.request(()=>{resetForm();cancelNotification();editOpen.value=false;void navigateTo(to.fullPath)});return false}})
onBeforeUnmount(()=>{disposed=true;logSequence++;logController?.abort();lifetime.abort();secret.value='';accessKeyId.value='';testPhone.value='';attempt.value=null})
</script>
<template><AdminConsole :refreshing="props.view==='logs'?logAction==='header':busy==='refresh'" @refresh="props.view==='logs'?loadLogs('header'):refresh()"><div class="space-y-5">
 <ConsolePageHeading :title="pageTitle"><template #actions><USelect v-if="data&&data.applications.length>1" :model-value="applicationKey" :items="data.applications.map(a=>({value:a.key,label:a.name}))" aria-label="短信所属应用" :disabled="!!busy||sending||notificationSaving" @update:model-value="refresh('application',$event)"/></template></ConsolePageHeading>
 <UAlert v-if="error" color="error" :title="error"><template v-if="!data" #actions><UButton :loading="busy==='retry'" @click="refresh('retry')">重试</UButton></template></UAlert>
 <ConsoleDataTable v-if="data&&props.view==='channels'&&applicationKey" :data="data.channels" :columns="channelColumns" :pagination="false" :show-sequence="false" min-table-width="340px"><template #config-cell="{row}"><UBadge :color="row.original.config.enabled?'success':'error'" variant="subtle">{{row.original.config.enabled?'已配置':'未配置'}}</UBadge></template><template #actions-cell="{row}"><UButton color="primary" variant="link" @click="openSettings(row.original.provider)">设置</UButton></template></ConsoleDataTable>
 <ConsoleDataTable v-if="data&&props.view==='notifications'&&applicationKey" :data="data.notifications" :columns="notificationColumns" :pagination="false" :show-sequence="false" min-table-width="340px"><template #enabled-cell="{row}"><UBadge :color="row.original.enabled?'success':'error'" variant="subtle">{{row.original.enabled?'已配置':'未配置'}}</UBadge></template><template #actions-cell="{row}"><UButton color="primary" variant="link" @click="openNotification(row.original)">设置</UButton></template></ConsoleDataTable>
<ConsoleDrawer :open="editOpen" :title="channel?.label||'短信设置'" description="配置服务商凭据，通知模板在通知设置中管理。" :dismissible="!busy&&!sending" @update:open="!$event&&closeSettings()"><template #body><UAlert v-if="error" color="error" :title="error" class="mb-5"/> <form v-if="data&&form&&channel&&applicationKey" id="sms-settings-form" class="space-y-5" @submit.prevent="save">
    <ConsoleSettingsField label="默认渠道"><UCheckbox v-model="makeDefault" label="设为默认短信渠道" :disabled="locked||channel.isDefault"/><p class="mt-2 text-xs text-muted">默认渠道配置缺失时会提示补齐；不会自动切换服务商。</p></ConsoleSettingsField>
    <ConsoleSettingsField label="短信签名" input-id="sms-signature"><ConsoleInput id="sms-signature" v-model="form.signature" :maxlength="100"  :disabled="locked" placeholder="已通过服务商审核的签名"/></ConsoleSettingsField>
    <ConsoleSettingsField v-if="provider==='tencent'" label="SDK AppID" input-id="sms-app"><ConsoleInput id="sms-app" v-model="form.appId" :maxlength="32"  :disabled="locked" placeholder="腾讯云短信应用 ID"/></ConsoleSettingsField>
    <ConsoleSettingsField v-if="provider==='tencent'" label="地域" input-id="sms-region"><ConsoleInput id="sms-region" v-model="form.region" :maxlength="50"  :disabled="locked" placeholder="ap-guangzhou"/></ConsoleSettingsField>
    <div class="border-t border-default pt-5"><h2 class="text-sm font-semibold">访问密钥</h2><p class="mt-1 text-xs text-muted">加密保存，留空保留已有密钥。{{channel.hasCredentials?'已保存 Key ID：'+channel.maskedAccessKeyId:'尚未保存密钥。'}}</p></div>
    <ConsoleSettingsField :label="provider==='aliyun'?'AccessKey ID':'SecretId'" input-id="sms-key"><ConsoleInput id="sms-key" v-model="accessKeyId" :maxlength="200" autocomplete="off" :disabled="locked||clearSecrets" :placeholder="channel.hasCredentials?'已保存，留空保留':'请输入访问 Key ID'"/></ConsoleSettingsField>
    <ConsoleSettingsField :label="provider==='aliyun'?'AccessKey Secret':'SecretKey'" input-id="sms-secret"><ConsoleInput id="sms-secret" v-model="secret" type="password" :maxlength="512" autocomplete="new-password" :disabled="locked||clearSecrets" :placeholder="channel.hasCredentials?'已保存，留空保留':'请输入访问密钥'"/></ConsoleSettingsField>
    <ConsoleSettingsField v-if="channel.hasCredentials" label="清除密钥"><UCheckbox v-model="clearSecrets" label="清除当前渠道已保存的密钥" :disabled="locked||!!accessKeyId||!!secret"/></ConsoleSettingsField>
    <div class="flex flex-wrap items-center justify-between gap-3 border-t border-default pt-5"><div><h2 class="text-sm font-semibold">配置自检</h2><p class="mt-1 text-xs text-muted">{{dirty?'请先保存当前修改。':'仅检查字段与请求签名，不发送短信。'}}</p></div><UButton type="button" color="neutral" variant="outline" icon="i-lucide-shield-check" :loading="busy==='check'" :disabled="locked||dirty||!data.version" @click="check">配置自检</UButton></div>
    <UAlert v-if="checkError" color="error" :title="checkError"/><UAlert v-if="checkResult" color="success" :title="checkResult.message" :description="'自检时间：'+dateTime(checkResult.checkedAt)"/>
    <div class="border-t border-default pt-5"><h2 class="text-sm font-semibold">短信测试</h2><p class="mt-1 text-xs text-muted">使用已保存的渠道配置和通知模板发送测试短信。</p></div>
    <ConsoleSettingsField label="测试手机号" input-id="sms-phone"><ConsoleInput id="sms-phone" v-model="testPhone" type="tel" inputmode="numeric" :maxlength="11" placeholder="请输入接收测试短信的手机号" :disabled="locked"/></ConsoleSettingsField>
    <ConsoleSettingsField label="短信用途" input-id="sms-purpose"><USelect id="sms-purpose" v-model="testPurpose" :items="[{value:'login',label:'用户登录'},{value:'register',label:'用户注册'},{value:'reset',label:'找回密码'}]" class="w-full" :disabled="locked"/></ConsoleSettingsField>
    <ConsoleSettingsField label="测试发送"><UButton type="button" color="neutral" variant="outline" icon="i-lucide-message-circle" :disabled="locked||dirty||!testPhone" @click="openTest">测试发送</UButton><p v-if="!data.testEnabled" class="mt-2 text-xs text-muted">短信发送未启用，可先保存服务商和模板配置。</p><p v-else class="mt-2 text-xs text-muted">可能产生服务商费用；测试验证码不能用于登录。</p></ConsoleSettingsField>
    <UAlert v-if="testError" color="error" :title="testError"/><UAlert v-if="testResult" :color="testResult.status==='ACCEPTED'?'success':'warning'" :title="testResult.message"/>
 </form></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" :disabled="!!busy||sending" @click="closeSettings">取消</UButton><UButton v-if="data?.canWrite" form="sms-settings-form" type="submit" :loading="busy==='save'" :disabled="!!busy||sending||!dirty">保存设置</UButton></ConsoleFormActions></template></ConsoleDrawer>
 <section v-if="applicationKey&&props.view==='logs'" class="space-y-4"><USelect :model-value="logChannel" :items="[{value:'sms',label:'短信'},{value:'wechat',label:'订阅消息'}]" aria-label="消息渠道" class="w-44" @update:model-value="changeLogChannel"/><div class="flex items-center justify-between gap-3"><div><p class="mt-1 text-xs text-muted">已受理表示服务商接受请求，实际送达请核对服务商记录。</p></div><ConsoleQueryButton kind="reset" color="neutral" variant="outline" :loading="logAction==='refresh'" @click="loadLogs('refresh')">刷新记录</ConsoleQueryButton></div>
  <ConsoleDataTable :data="logs.items" :columns="columns" :total="logs.total" :page="logs.page" :page-size="logs.pageSize" :page-size-items="[10,20,50]" :client-pagination="false" :error="logsError" empty-title="暂无发送记录" empty-description="通知任务会在这里显示处理结果。" min-table-width="850px" @retry="loadLogs('retry')" @update:page="loadLogs('page',$event)" @update:page-size="loadLogs('page',1,$event)">
   <template #provider-cell="{row}">{{row.original.provider==='wechat'?'微信':row.original.provider==='aliyun'?'阿里云':'腾讯云'}}</template><template #status-cell="{row}"><UBadge :color="row.original.status==='ACCEPTED'?'success':row.original.status==='FAILED'?'error':'warning'" variant="subtle">{{statusLabels[row.original.status]||row.original.status}}</UBadge></template><template #receipt-cell="{row}"><span class="text-xs">{{row.original.receipt||row.original.errorCode||'—'}}</span></template><template #createdAt-cell="{row}">{{dateTime(row.original.createdAt)}}</template>
  </ConsoleDataTable>
 </section>
 <ConsoleDrawer :open="notificationOpen" title="编辑通知设置" :description="notificationForm?.label||''" :dismissible="!notificationSaving" @update:open="!$event&&closeNotification()"><template #body><form v-if="notificationForm" id="notification-settings-form" class="space-y-6" @submit.prevent="saveNotification">
  <section class="space-y-4"><h3 class="drawer-section-title">通知信息</h3><dl class="drawer-facts"><dt>通知名称</dt><dd>{{notificationForm.label}}</dd><dt>通知类型</dt><dd>{{notificationForm.typeLabel}}</dd><dt>通知业务</dt><dd>{{notificationForm.business}}</dd></dl></section>
  <h3 class="drawer-form-section">短信通知</h3>
  <ConsoleSettingsField label="模板 ID" input-id="notification-template"><ConsoleInput id="notification-template" v-model="notificationForm.templateId" :maxlength="100"  placeholder="请输入模板 ID" :disabled="notificationSaving||!data?.canWrite||!notificationForm.provider"/><p class="mt-2 text-xs text-muted">{{notificationForm.provider?'当前短信渠道：'+notificationForm.providerLabel:'请先在短信配置中配置并选择默认渠道。'}}</p></ConsoleSettingsField>
  <ConsoleSettingsField label="短信内容" input-id="notification-content"><UTextarea id="notification-content" v-model="notificationForm.content" :rows="6" :maxlength="500" required class="w-full" placeholder="请输入短信内容，使用 {code} 表示验证码" :disabled="notificationSaving||!data?.canWrite"/><div class="mt-2 space-y-2 text-xs leading-5 text-muted"><p>可选变量：验证码 {code}</p><p>示例：您的验证码为{code}，请勿泄露给他人。</p><p>请与服务商已审核模板保持一致；实际短信按服务商模板发送。</p></div></ConsoleSettingsField>
  <UAlert v-if="notificationError" variant="subtle" color="error" :title="notificationError"/>
 </form></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" :disabled="notificationSaving" @click="closeNotification">取消</UButton><UButton v-if="data?.canWrite" type="submit" form="notification-settings-form" :loading="notificationSaving" :disabled="notificationSaving||!notificationDirty">保存设置</UButton></ConsoleFormActions></template></ConsoleDrawer>
 <ConsoleDiscardChangesDialog :controller="discard"/>
 <UModal :open="testOpen" title="确认发送测试短信？" :description="'接收号码：'+testPhone+'。使用已保存配置，可能产生服务商费用；相同请求会返回原结果。'" :dismissible="!sending" @update:open="!$event&&closeTest()"><template #body><UAlert v-if="!data?.testEnabled" color="warning" title="短信发送未启用"/><UAlert v-if="testError" color="error" :title="testError"/><UAlert v-if="testResult" :color="testResult.status==='ACCEPTED'?'success':'warning'" :title="testResult.message"/></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" :disabled="sending" @click="closeTest">关闭</UButton><UButton :loading="sending" :disabled="sending||!data?.testEnabled" @click="sendTest">{{attempt?'提交 / 查询原请求':'确认发送'}}</UButton></ConsoleFormActions></template></UModal>
</div></AdminConsole></template>
